query:
NODE VALUE out_degree SumAgg<INT64> = 0
TABLE degrees {id STRING, degree INT64}

MATCH (s:player)-[e:follow]->(t:player)
PER PATH {
  SET s.@out_degree += 1
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id AS id, p.@out_degree AS degree INTO degrees
}

FOR row IN degrees
RETURN row.id AS id, row.degree AS degree
